# Training-only computational profile; no qualification or accuracy claim.
source('validation/autodesn/load_checkout.R')
root<-'validation/autodesn/remediation';out<-file.path(root,'artifacts/profile_full_bank')
dir.create(out,recursive=TRUE,showWarnings=FALSE)
Rcpp::sourceCpp('src/autodesn_rhs.cpp',cacheDir=file.path(root,'artifacts/cpp'),showOutput=FALSE)
m<-jsonlite::fromJSON(file.path(root,'artifacts/inference_cache_manifest.json'))
stopifnot(identical(digest::digest(file=m$path,algo='sha256'),m$sha256))
b<-readRDS(m$path);b$extension<-readRDS(m$extensions$F1$path);class(b)<-c('autodesn_extended_bank',class(b))
qpath<-file.path(root,'artifacts/F1/frozen_proposal_128.rds')
lpath<-file.path(root,'artifacts/F1/frozen_local_proposal_128.rds')
q<-readRDS(qpath);lp<-readRDS(lpath)
stopifnot(identical(q$bank_id,b$extension$id),identical(lp$proposal$bank_id,b$extension$id))
Rprof(file.path(out,'profile.out'),interval=.001)
fit<-autodesn_fit_bank(b,n_burn=500L,n_mcmc=2000L,beta_prior='rhs',rhs_control=list(tau0=.001,slab_scale=1,slab_df=4,interweave_global=TRUE),model_control=list(moves=4L,joint_moves=2L,save_draws=128L,proposal=q$model,period_proposal=q$period,joint_proposal=q$joint,local_proposal=lp$proposal,local_moves=1L,local_scale_proposal=TRUE),initial_variance=1,seed=9366021L,backend='cpp')
Rprof(NULL)
profile<-summaryRprof(file.path(out,'profile.out'))
write.csv(profile$by.self,file.path(root,'evidence/full_bank_profile_by_self.csv'))
write.csv(profile$by.total,file.path(root,'evidence/full_bank_profile_by_total.csv'))
record<-list(complete=TRUE,target_id=fit$controls$target_id,burn=500L,retained=2000L,seed=9366021L,computation=fit$computation,profile_sampling_seconds=profile$sampling.time,source_sha256=as.list(setNames(vapply(.autodesn_source_paths,function(p)digest::digest(file=p,algo='sha256'),''),.autodesn_source_paths)),proposal_sha256=digest::digest(file=qpath,algo='sha256'),local_proposal_sha256=digest::digest(file=lpath,algo='sha256'),test_outcomes_used=FALSE,scope='Single training-only short computational profile; instrumented time is not a production runtime benchmark and does not qualify a posterior')
jsonlite::write_json(record,file.path(root,'evidence/full_bank_profile.json'),pretty=TRUE,auto_unbox=TRUE)
print(head(profile$by.self,12))
